 let importSession=$state<api.ResearchDocument|null>(null);let importSessions=$state<api.ResearchDocument[]>([]);let importName=$state('');let importState=$state<api.ImportSessionState|null>(null);let dropped=$state<api.ResearchDrop|null>(null);let metadataFilter=$state<Partial<api.ResearchResultFilter>>({});
