 let newRowValue=$state('');let newRowKind=$state<api.SelectorKind>('username');let rowOffset=$state(0);let configured=$state<Record<string,boolean>>({});let options=$state<api.ProviderOptions>({paid_authorized:false,face_eligible:false,premium:false,exact_match:true,image_category:'similar',page:1,domain_filter:'',sort_type:'QUALITY_DESCENDING'});
 let rows=$state<api.BulkRow[]>([]);let chosen=$state<number[]>([]);let submittedKeys=$state<string[]>([]);let prepared=$state<api.PreparedResearch|null>(null);let consent=$state(false);let rescan=$state(false);let safe=$state(true);
