 let runs=$state<api.ResearchPage<api.ResearchRun>|null>(null);let runOffset=$state(0);
 let toolQuery=$state('');let category=$state('');let favoritesOnly=$state(false);let toolOffset=$state(0);let toolDetail=$state<api.DirectoryTool|null>(null);let tree=$state(false);let detailElement=$state<HTMLElement>();let detailTrigger:HTMLElement|null=null;
 let prefs=$state<api.ResearchDocument|null>(null);let stars=$state<string[]>([]);let ratings=$state<Record<string,number>>({});let notes=$state<Record<string,string>>({});let drafts=$state<Record<string,string>>({});
 let exportConsent=$state(false);let exportFormat=$state<'csv'|'json'>('csv');
