 async function load(){try{const [registry,catalog,p,history,c]=await Promise.all([api.researchRegistry(),api.researchDirectory(),api.researchDocuments(generation,'tool_preferences'),api.researchRuns(generation),api.researchDocuments(generation,'collection')]);const saved=await api.researchDocuments(generation,'saved_search');if(live){importSessions=saved.filter(d=>d.payload.purpose==='import_session');localHistory=saved.filter(d=>d.payload.purpose==='local_query').flatMap(d=>(d.payload.selectors as api.Selector[])??[]);}if(!live)return;sources=registry;tools=catalog;runs=history;collections=c;prefs=p[0]??null;stars=(prefs?.payload.stars as string[])??[];sourceFavorites=(prefs?.payload.source_favorites as string[])??[];ratings=(prefs?.payload.ratings as Record<string,number>)??{};notes=(prefs?.payload.notes as Record<string,string>)??{};drafts=(prefs?.payload.drafts as Record<string,string>)??{};}catch(e){fail(e);}}
 async function savePrefs(){try{pending=true;prefs=await api.researchDocumentSave(generation,{id:'directory-preferences',revision:prefs?.revision??0,kind:'tool_preferences',name:'Tool directory preferences',payload:{version:1,stars,source_favorites:sourceFavorites,ratings,notes,drafts},archived:false,updated_utc:''});status='Saved inside this encrypted case.';}catch(e){fail(e);}finally{pending=false;}}
 function randomUsername(){const words=['cedar','river','copper','night','mesa','raven'];const data=crypto.getRandomValues(new Uint32Array(3));query=`${words[data[0]%words.length]}_${words[data[1]%words.length]}${data[2]%10000}`;}
 function domainVariant(suffix:string){query=`${query.trim()}.${suffix}`;kind='domain';changeKind();}
 function changeKind(){selectedSources=sources.filter(s=>s.delivery==='native'&&s.selectors.includes(kind)).map(s=>s.id);}
 async function importFile(){const n=++serial;pending=true;error=null;try{const selection=await api.selectPath('research_import',generation);if(!selection)return;const t=await api.researchImportPreview(generation,selection,importFormat,importHeader);const suggestions=await api.researchTableSuggestions(t);if(live&&n===serial){table=t;importColumn=0;joinColumn=-1;rows=[];chosen=[];importSession=null;importState=null;submittedKeys=[];candidateWarnings=[];columnSuggestions=suggestions;}}catch(e){fail(e);}finally{if(live)pending=false;}}
