 async function rowType(index:number,next:api.SelectorKind){importSession=null;importState=null;submittedKeys=[];try{const selector=await api.researchSelector(next,rows[index].value);rows=rows.map((r,i)=>i===index?{...r,kind:next,selector,error:null}:r);}catch(e){rows=rows.map((r,i)=>i===index?{...r,kind:next,selector:null,error:api.asCommandError(e).message}:r);chosen=chosen.filter(i=>i!==index);}}
