 let imageRow=$state(-1);
 async function selectImage(id:string){if(imageRow<0){query=id;return;}const index=imageRow;try{const selector=await api.researchSelector('image',id);rows=rows.map((r,i)=>i===index?{...r,value:id,kind:'image',selector,error:null,origin_ids:[]}:r);importSession=null;importState=null;submittedKeys=[];imageRow=-1;}catch(e){fail(e);}}
 function detachImport(){importSession=null;importState=null;submittedKeys=[];}
 function removeRow(index:number){detachImport();rows=rows.filter((_,i)=>i!==index);chosen=chosen.filter(i=>i!==index).map(i=>i>index?i-1:i);rowOffset=Math.min(rowOffset,Math.max(0,Math.floor((rows.length-1)/50)*50));}
 async function addRow(){if(rows.length>=20000||!newRowValue.trim())return;pending=true;error=null;try{let row:api.BulkRow;try{const selector=await api.researchSelector(newRowKind,newRowValue);row={value:newRowValue.trim(),kind:newRowKind,selector,error:null,repeats:1,origin_ids:[]};}catch(e){row={value:newRowValue.trim(),kind:newRowKind,selector:null,error:api.asCommandError(e).message,repeats:1,origin_ids:[]};}if(!live)return;detachImport();const index=rows.findIndex(r=>r.kind===row.kind&&r.selector&&row.selector&&r.selector.normalized===row.selector.normalized);if(index>=0){rows=rows.map((r,i)=>i===index?{...r,repeats:r.repeats+1}:r);rowOffset=Math.floor(index/50)*50;}else{rows=[...rows,row];rowOffset=Math.floor((rows.length-1)/50)*50;}newRowValue='';}finally{if(live)pending=false;}}
 async function archiveImport(doc:api.ResearchDocument){try{await api.researchDocumentSave(generation,{...doc,archived:true});importSessions=importSessions.filter(d=>d.id!==doc.id);if(importSession?.id===doc.id)detachImport();}catch(e){fail(e);}}
 function rowKey(row:api.BulkRow){return `${row.kind}:${row.selector?.normalized??row.value}`;}
 function nextBatch(){chosen=rows.flatMap((row,i)=>row.selector&&!submittedKeys.includes(rowKey(row))?[i]:[]).slice(0,15);prepared=null;consent=false;status=chosen.length?'Selected the next unsubmitted queries for local review.':'All valid queries in this preview were submitted. Review run history before repeating them.';}
 async function start(){if(!prepared||!consent||!online)return;pending=true;error=null;try{job=await api.startOperation('research_run',{token:prepared.token,digest:prepared.digest,consent:true},generation);if(!live){void api.cancelOperation(job).catch(()=>{});return;}if(batch)submittedKeys=[...new Set([...submittedKeys,...chosen.map(i=>rowKey(rows[i]))])];runId=job;results=null;outcome='all';resultSource='';resultCategory='';resultOffset=0;resultSelection=[];prepared=null;consent=false;await poll();}catch(e){fail(e);}finally{if(live)pending=false;}}
 async function poll(){if(!live||!job)return;try{const op=await api.operationStatus(job);if(!live)return;operation=op;await refreshResults();if(op.status==='running'){timer=setTimeout(()=>void poll(),700);}else{runs=await api.researchRuns(generation,runOffset);if(importSession)importState=await api.researchImportSession(generation,importSession.id);}}catch(e){fail(e);}}
 async function refreshResults(){if(!runId)return;const n=++resultSerial;const id=runId;resultLoading=true;try{const p=await api.researchResults(generation,id,resultOffset,resultFilter);if(live&&n===resultSerial&&id===runId)results=p;}finally{if(live&&n===resultSerial)resultLoading=false;}}
 async function pageResults(offset:number){resultOffset=offset;try{await refreshResults();}catch(e){fail(e);}}
 async function pageRuns(offset:number){try{runOffset=offset;runs=await api.researchRuns(generation,offset);}catch(e){fail(e);}}
 async function openRun(id:string){runId=id;results=null;outcome='all';resultSource='';resultCategory='';resultOffset=0;resultSelection=[];pane='lookups';try{await refreshResults();}catch(e){fail(e);}}
 async function saveCollection(){if(!resultSelection.length)return;pending=true;error=null;try{const existing=collections.find(c=>c.id===collectionTarget);const ids=[...new Set([...((existing?.payload.result_ids as string[])??[]),...resultSelection])];const doc=await api.researchDocumentSave(generation,{id:existing?.id??crypto.randomUUID(),revision:existing?.revision??0,kind:'collection',name:existing?.name??collectionName.trim(),payload:{version:1,result_ids:ids},archived:false,updated_utc:''});collections=[doc,...collections.filter(c=>c.id!==doc.id)];status=`Saved ${resultSelection.length} selected results to ${doc.name}.`;resultSelection=[];}catch(e){fail(e);}finally{pending=false;}}
 async function exportSelected(){if(!exportConsent||!resultSelection.length)return;try{const destination=await api.selectPath(exportFormat==='csv'?'research_csv':'research_json',generation);if(!destination)return;job=await api.startOperation('research_export',{destination,format:exportFormat,result_ids:resultSelection,plaintext_consent:true},generation);exportConsent=false;await poll();}catch(e){fail(e);}}
 async function archive(c:api.ResearchDocument){try{await api.researchDocumentSave(generation,{...c,archived:true});collections=collections.filter(v=>v.id!==c.id);}catch(e){fail(e);}}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);status='Copied.';}catch{status='Clipboard unavailable; select and copy the displayed text.';}}
 async function providerStatus(id:string){try{const s=await api.researchProviderStatus(id);configured={...configured,[id]:s.configured};status=!s.supported?'Native provider credential storage is unavailable on this platform. Use the official browser workflow and Evidence import.':s.configured?'Credential is available in native storage. Usage/credits are not checked; account and regional eligibility remain unverified. No request was sent.':`Create a Generic Password in Keychain Access: service com.kokin.osint, account ${s.credential_account??id}, password set to your provider API key. The key never enters this form.`;}catch(e){fail(e);}}
 async function reviewCandidate(id:string,action:'create_entity'|'add_identifier'|'relate',index?:number){pending=true;error=null;try{const candidate=await api.researchReviewCandidate(generation,id,index);if(live)onCandidate?.(candidate,action);}catch(e){fail(e);}finally{if(live)pending=false;}}
 async function showTool(tool:api.DirectoryTool,trigger?:HTMLElement){detailTrigger=trigger??(document.activeElement instanceof HTMLElement?document.activeElement:null);toolDetail=tool;await tick();detailElement?.focus();}
 async function closeTool(){const trigger=detailTrigger;toolDetail=null;await tick();trigger?.focus();}
 function profileSummary(r:api.ResearchResult){const f=r.fields;const name=typeof f.name==='string'?f.name:typeof f.full_name==='string'?f.full_name:'';const count=typeof f.followers==='number'?f.followers:typeof f.followers_count==='number'?f.followers_count:null;return {name,followers:count};}
 function registrationDate(r:api.ResearchResult){if(r.source!=='rdap'||!Array.isArray(r.fields.events))return '';const event=r.fields.events.find((e:unknown)=>typeof e==='object'&&e!==null&&(e as Record<string,unknown>).eventAction==='registration') as Record<string,unknown>|undefined;return typeof event?.eventDate==='string'?event.eventDate:'';}
 function ageText(utc:string){const seconds=Math.max(0,Math.floor((Date.now()-Date.parse(utc))/1000));if(!Number.isFinite(seconds))return 'Age unknown';return seconds<60?'less than a minute ago':seconds<3600?`${Math.floor(seconds/60)} minutes ago`:`${Math.floor(seconds/3600)} hours ago`;}
 function focusQuery(e:KeyboardEvent){if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!(e.target instanceof HTMLElement&&e.target.closest('input,textarea,select,[contenteditable="true"]'))){e.preventDefault();pane='lookups';void tick().then(()=>document.querySelector<HTMLInputElement>('.query-form input[maxlength]')?.focus());}}
 function external(url:string):string|undefined{try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:undefined;}catch{return;}}
</script>

<svelte:window onkeydown={focusQuery}/>
<section class="research" aria-label="Research and tools">
 <header><h2>Research and tools</h2><p>Follow public leads, keep their evidence, and review what they mean. External checks start only after you review a request. Press / outside a form to focus the selector.</p></header>
 <nav aria-label="Research views">{#each [['lookups','Lookups'],['directory','Tool directory'],['history','Run history'],['collections','Collections']] as [id,label]}<button class:current={pane===id} aria-pressed={pane===id} onclick={()=>pane=id}>{label}</button>{/each}</nav>
 {#if error}<ErrorNotice {error}/>{/if}
 {#if status}<p role="status">{status}</p>{/if}
 {#if pane==='lookups'}
  <div class="query-form">
   <label>Selector type<select bind:value={kind} onchange={changeKind}>{#each kinds as k}<option value={k}>{k}</option>{/each}</select></label>
   <label class="toggle"><input type="checkbox" bind:checked={batch}/>Batch · select up to 15 queries</label>
   <label class="wide">{batch?'Pasted selectors':'Selector'}{#if batch}<textarea bind:value={query} rows="4" maxlength="2000000" placeholder="One query per line. Preview and select rows before preparing a request."></textarea>{:else}<input bind:value={query} maxlength="2048" list="case-research-suggestions" onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();if(!pending&&operation?.status!=='running')void localSearch();}else if(e.key==='Escape'){query='';}}} placeholder={kind==='phone'?'+1 602 555 0123':kind==='image'?'Choose an imported image or enter its artifact ID':kind==='domain'?'example.org':'Enter a public selector'}/>{/if}</label>
   {#if batch}<p class="wide">Drop one local file up to 64 MiB into this window. Text table previews use a 2 MB bound; PDF/image processing uses the native Evidence limits.</p><button disabled={pending||!query} onclick={previewBatch}>Preview pasted queries</button><button disabled={pending||!query} onclick={previewCandidates}>Extract mixed candidates locally</button><label>File format<select bind:value={importFormat}>{#each ['csv','tsv','json','text','md','log'] as f}<option>{f}</option>{/each}</select></label><label class="toggle"><input type="checkbox" bind:checked={importHeader}/>First delimited row contains column names</label><button disabled={pending} onclick={importFile}>Choose file for local preview</button>{/if}
  </div>
  <div class="actions"><button disabled={pending||(!batch&&!query)||(batch&&!chosen.length)} onclick={()=>localSearch()}>Search encrypted case</button><span>Default: local processing · zero external requests</span></div>
