  {#if dropped}<section aria-label="Dropped research file"><h3>{dropped.name}</h3><p>Only this dropped file was selected. Choose a local preview for text tables, or import a PDF/image as encrypted Evidence. The format above controls table parsing.</p><button disabled={pending} onclick={previewDrop}>Preview dropped text file</button>{#if operations}<button disabled={pending||operations.busy} onclick={importDropEvidence}>Import dropped PDF or image as Evidence</button>{/if}<button onclick={()=>dropped=null}>Dismiss dropped file</button></section>{/if}
  {#if batch}<details class="import-workspaces"><summary>Saved import workspaces · {importSessions.length}</summary><p>Save all rows to resume successive batches after closing the case. Saved rows contain private identifiers and remain encrypted. Saving does not run a query.</p>{#each importSessions as session}<button disabled={pending} onclick={()=>openImport(session.id)}>Resume {session.name}</button><button disabled={pending} onclick={()=>archiveImport(session)}>Archive import {session.name}</button>{/each}{#if rows.length}<label>Import workspace name<input bind:value={importName} maxlength="120"/></label><button disabled={pending||!importName.trim()} onclick={saveImport}>Save all preview rows</button>{/if}{#if importState}<p>{importState.submitted_keys.length} distinct queries submitted across {importState.runs.total} runs. Submitted does not mean all sources completed.</p>{#each importState.runs.rows as run}<button onclick={()=>openRun(run.id)}>{run.status} · {run.completed}/{run.expected} saved source results · {run.created_utc}</button>{/each}<button disabled={pending||!importState.runs.offset} onclick={()=>pageImportRuns(Math.max(0,importState!.runs.offset-50))}>Previous import runs</button><button disabled={pending||importState.runs.offset+50>=importState.runs.total} onclick={()=>pageImportRuns(importState!.runs.offset+50)}>Next import runs</button>{/if}</details>{/if}
