  {#if mediaPage&&(kind==='image'||imageRow>=0)}<section aria-label="Query image selection"><h3>Select encrypted image evidence</h3><p>Selecting an image only fills a query reference. External upload needs a separate reviewed request.</p>{#each mediaPage.rows.filter(a=>['image/jpeg','image/png','image/webp'].includes(a.media_type)) as image}<button onclick={()=>selectImage(image.artifact_id)}>{image.canonical_locator??image.artifact_id} · {image.media_type} · {image.byte_length} bytes</button>{/each}<button disabled={pending||!mediaOffset} onclick={()=>loadMedia(Math.max(0,mediaOffset-50))}>Previous query images</button><button disabled={pending||mediaOffset+50>=mediaPage.total} onclick={()=>loadMedia(mediaOffset+50)}>Next query images</button></section>{/if}
