  {#if !batch&&kind==='username'}<div class="actions" aria-label="Local username suggestions"><span>Try locally:</span>{#each ['researcher','blue_mesa','night_ledger'] as example}<button onclick={()=>query=example}>{example}</button>{/each}<button onclick={randomUsername}>Random username</button><button onclick={()=>query=''}>Clear query</button></div>{/if}
