  {#if batch}<details class="evidence-preview"><summary>PDF and OCR evidence → reviewed candidates</summary><p>Import a PDF or image into Evidence and run its native extraction. This preview reads authenticated, current transformation snapshots locally. It never uploads the document.</p>{#if operations}<button disabled={pending||operations.busy} onclick={()=>operations?.importFile()}>Import PDF or image into Evidence</button>{/if}<button disabled={pending} onclick={()=>loadMedia()}>Load case media sources</button>{#if mediaPage}<label>Imported PDF or OCR image<select bind:value={evidenceArtifact}><option value="">Choose a source</option>{#each mediaPage.rows.filter(a=>['application/pdf','image/jpeg','image/png','image/webp','image/tiff'].includes(a.media_type)) as a}<option value={a.artifact_id}>{a.canonical_locator??a.artifact_id} · {a.observations} observations</option>{/each}</select></label><div class="actions"><button disabled={pending||!mediaOffset} onclick={()=>loadMedia(Math.max(0,mediaOffset-50))}>Previous evidence page</button><button disabled={pending||mediaOffset+50>=mediaPage.total} onclick={()=>loadMedia(mediaOffset+50)}>Next evidence page</button></div>{/if}<label>Evidence artifact ID<input bind:value={evidenceArtifact} maxlength="128"/></label>{#if operations}<label class="toggle"><input type="checkbox" bind:checked={ocrEvidence}/>Use installed OCR for this source's first page</label><button disabled={pending||operations.busy||!evidenceArtifact} onclick={()=>operations?.run('media_extract',{version:1,artifact_id:evidenceArtifact,page:0,ocr:ocrEvidence})}>Extract selected evidence locally</button>{/if}<button disabled={pending||operations?.busy||!evidenceArtifact} onclick={previewEvidence}>Preview candidates from evidence</button>{#if evidenceArtifact}<button onclick={()=>onopen(evidenceArtifact)}>Inspect original evidence</button>{/if}<p>OCR page selection and additional extraction controls are available in Evidence. New candidates start unselected; review and choose up to 15.</p></details>{/if}
  {#if batch&&table}<section aria-label="Import column mapping"><h3>Map imported selectors</h3><p>{table.rows.length} rows · {table.columns.length} columns. File preview is local; nothing has been sent.</p>{#each table.warnings as warning}<p>{warning}</p>{/each}<label>Selector column<select bind:value={importColumn}>{#each table.columns as column,i}<option value={i}>{column||`Column ${i+1}`}</option>{/each}</select></label>{#if kind==='name'}<label>Second name column<select bind:value={joinColumn}><option value={-1}>Do not join</option>{#each table.columns as c,i}{#if i!==importColumn}<option value={i}>{c}</option>{/if}{/each}</select></label>{/if}{#if columnSuggestions.length}<details><summary>Suggested column types · review before applying</summary>{#each columnSuggestions as s}<button onclick={()=>{kind=s.kind;changeKind();importColumn=s.column;joinColumn=-1;}}>{table.columns[s.column]} → {s.kind} · {s.valid}/{s.sampled} sample values · {s.basis}</button>{/each}</details>{/if}<pre>{table.rows.slice(0,3).map(r=>r[importColumn]??'').join('\n')}</pre><button disabled={pending} onclick={previewTable}>Validate mapped column</button><button disabled={pending} onclick={previewColumnCandidates}>Extract mixed candidates from this column</button></section>{/if}
