  {#if rows.length}<section aria-label="Batch preview"><h3>Review extracted queries</h3><div class="actions"><button disabled={pending||operation?.status==='running'} onclick={()=>chosen=[]}>Clear batch selection</button><button disabled={pending||operation?.status==='running'} onclick={nextBatch}>Select next 15 unsubmitted queries</button></div>{#each candidateWarnings as warning}<p>{warning}</p>{/each}<p>{rows.length} distinct rows. {chosen.length} selected; the rest remain available for another batch.</p><div class="batch-rows">{#each rows.slice(rowOffset,rowOffset+50) as row,j}{@const i=rowOffset+j}<label class="batch-row"><input type="checkbox" bind:group={chosen} value={i} disabled={!row.selector||(!chosen.includes(i)&&chosen.length>=15)}/><span>{row.selector?.normalized??row.value}</span><select aria-label={`Type for imported row ${i+1}`} value={row.kind} onchange={e=>rowType(i,e.currentTarget.value as api.SelectorKind)}>{#each kinds as k}<option>{k}</option>{/each}</select><button type="button" disabled={pending} onclick={()=>chooseImage(i)}>Choose image for row {i+1}</button><button type="button" disabled={pending} onclick={()=>removeRow(i)}>Remove row {i+1}</button><small>{row.error??`${row.repeats} occurrence${row.repeats===1?'':'s'}`}{#if row.origin_ids?.length}<br/>Origin: {row.origin_ids.join(', ')}{/if}</small></label>{/each}</div><div class="actions"><button disabled={rowOffset===0} onclick={()=>rowOffset=Math.max(0,rowOffset-50)}>Previous imported rows</button><span>{rowOffset+1}–{Math.min(rowOffset+50,rows.length)}</span><button disabled={rowOffset+50>=rows.length} onclick={()=>rowOffset+=50}>Next imported rows</button></div></section>{/if}
