  <label class="toggle"><input type="checkbox" bind:checked={options.paid_authorized}/>Prepare this paid request for final review.</label></fieldset>{/if}
  <button disabled={pending||operation?.status==='running'||!selectedSources.length||(!batch&&!query)||(batch&&!chosen.length)} onclick={prepare}>Review research request</button>
  {#if prepared}<section class="disclosure" aria-label="Research request disclosure"><h3>Before these checks run</h3><p>{prepared.plan.limitation}</p><ul>{#each prepared.plan.selectors??[] as s}<li>{s.kind}: <code>{s.normalized}</code>{#if s.original!==s.normalized} (original: {s.original}){/if}</li>{/each}</ul>{#if prepared.plan.input_origins?.length}<p>{prepared.plan.input_origins.length} selected query origins are linked to current case observations. Origin references are not sent to providers.</p>{/if}<p>Maximum {prepared.plan.max_calls} requests. Your network address is visible to each destination. Cached evidence retains its original observation time.</p><ul>{#each prepared.plan.image_disclosures??[] as image}<li>Upload original image {image.artifact_id} · {image.media_type} · {(image.byte_length/1024/1024).toFixed(2)} MiB · content hash <code>{image.content_hash}</code></li>{/each}</ul><ul>{#each Object.entries(prepared.plan.provider_call_limits) as [provider,calls]}<li>{provider}: at most {calls} calls{#if prepared.plan.provider_credit_upper_bounds[provider]} and {prepared.plan.provider_credit_upper_bounds[provider]} credits{/if}. Entitlement and actual billing remain provider controlled.</li>{/each}</ul><ul>{#each prepared.plan.request_urls as u}<li><code>{u}</code></li>{/each}</ul><label class="toggle"><input type="checkbox" bind:checked={consent}/>I authorize these queries and destinations.</label><button disabled={!consent||!online||pending||operation?.status==='running'} onclick={start}>Start reviewed checks</button>{#if !online}<p>Enable online mode in the case toolbar to start.</p>{/if}</section>{/if}
  </details>
